const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const MODEL_ID='Xenova/all-MiniLM-L6-v2';
let aiTask=null;let study,activeRun=null,rows=[],view='overview',page=1,screenBusy=false,aiBusy=false,worker=null,requestId=0,workerReady=false,modelCache={},pending=new Map(),conversation=[];
let saved=new Set(),audit=[];try{saved=new Set(JSON.parse(localStorage.getItem('fairouz-v2-shortlist')||'[]'));audit=JSON.parse(localStorage.getItem('fairouz-v2-audit')||'[]');if(!Array.isArray(audit))audit=[]}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem('fairouz-v2-shortlist',JSON.stringify([...saved]));localStorage.setItem('fairouz-v2-audit',JSON.stringify(audit.slice(-100)))}catch{toast('Browser storage unavailable; export the run to keep a copy.')}}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function numeric(x,d=2){return Number(x).toFixed(d)}function nm(x){return x<.01?x.toExponential(2):x<1?numeric(x,3):x<1000?numeric(x,1):x.toExponential(2)}
function updateButtons(){const enabled=!!activeRun&&!aiBusy;$('#chatSend').disabled=!enabled;$('#summarise').disabled=!enabled;$('#runButton').disabled=!study||screenBusy||aiBusy||$('#virus').value==='custom'}
function filtered(){const q=$('#search').value.trim().toLowerCase(),f=$('#filter').value;return rows.filter(c=>(!q||(c.id+' '+c.smiles).toLowerCase().includes(q))&&(view!=='shortlist'||saved.has(c.id))&&(f!=='saved'||saved.has(c.id))&&(f!=='low'||c.similarity<.4))}
function render(){const list=filtered();const pages=Math.max(1,Math.ceil(list.length/20));page=Math.min(page,pages);const subset=list.slice((page-1)*20,page*20);$('#compoundRows').innerHTML=subset.length?subset.map(c=>`<tr class="${c.rank<=3?'top-ranked':''}"><td class="rank-number">${c.rank}</td><td><button class="compound-link" data-detail="${c.id}"><span><strong>${c.id}</strong><small title="${escape(c.smiles)}">${escape(c.smiles)}</small></span></button></td><td class="prediction">${numeric(c.prediction,3)}</td><td class="nm">${nm(c.equivalentNm)}</td><td class="tree-sd">${numeric(c.treeSd,3)}</td><td><span class="sim ${c.similarity<.4?'low':''}">${numeric(c.similarity,2)}<small class="sim-note">${c.similarity<.4?'LOW SIMILARITY':'SYNTHETIC REF.'}</small></span></td><td><button class="save ${saved.has(c.id)?'saved':''}" data-save="${c.id}" aria-label="${saved.has(c.id)?'Remove':'Save'} ${c.id}" aria-pressed="${saved.has(c.id)}">${saved.has(c.id)?'★':'☆'}</button></td></tr>`).join(''):`<tr><td colspan="7">${activeRun?(view==='shortlist'?'No saved compounds match this view. Save a compound with the star beside its row, or clear your filters.':'No compounds match. Try another ID or clear your filters.'):'Run screening to generate predictions.'}</td></tr>`;$('#savedCount').textContent=saved.size;$('#statSaved').textContent=saved.size;$('#resultCount').textContent=list.length;$('#runs').textContent=audit.length;$('#tableSummary').textContent=`${list.length} results · synthetic pIC50 · not measured`;$('#pageLabel').textContent=`${page} / ${pages}`;$('#prevPage').disabled=page<=1;$('#nextPage').disabled=page>=pages;$('#resultsTitle').textContent=view==='shortlist'?'Saved compounds':'Top compounds';renderAudit();renderAssays()}
function plot(){if(!rows.length)return;const maxSd=Math.max(...rows.map(c=>c.treeSd))||1;$('#dots').innerHTML=rows.map(c=>`<button class="dot ${c.similarity<.4?'pale':''}" style="left:${5+90*c.treeSd/maxSd}%;bottom:${Math.max(2,Math.min(98,(c.prediction-2)/8*100))}%" title="${c.id} | synthetic pIC50 ${numeric(c.prediction,3)} | tree SD ${numeric(c.treeSd,3)}" aria-label="Inspect ${c.id}" data-detail="${c.id}"></button>`).join('');$('.x-label').innerHTML=`Tree SD: 0 <span>${numeric(maxSd,2)} pIC50 units →</span>`}
function renderAssays(){const q=$('#assaySearch').value.trim().toLowerCase();const list=rows.filter(c=>!q||c.id.toLowerCase().includes(q));$('#assayRows').innerHTML=list.map(c=>{const p=c.assayPlaceholder;return `<tr><td>${c.rank}</td><td><button class="compound-link" data-detail="${c.id}"><strong>${c.id}</strong></button></td><td>${numeric(p.ic50.mean,3)} &plusmn; ${numeric(p.ic50.sd,3)}</td><td>${numeric(p.ec50.mean,3)} &plusmn; ${numeric(p.ec50.sd,3)}</td><td>${numeric(p.cc50.mean,3)} &plusmn; ${numeric(p.cc50.sd,3)}</td><td>${numeric(p.selectivityIndex,2)}</td><td><span class="priority explore">NOT PERFORMED</span></td></tr>`}).join('')||'<tr><td colspan="7">No matching candidate placeholders.</td></tr>';$('#assayCount').textContent=list.length;$('#assayContext').textContent=activeRun?`${activeRun.virus} / ${activeRun.target} | ${activeRun.id} | model order retained`:'Run screening to load placeholders.'}
function renderAudit(){$('#auditRows').innerHTML=audit.length?audit.slice().reverse().map(a=>`<article class="audit-record"><strong>${escape(a.id)} · ${escape(a.virus)}</strong><small>${escape(new Date(a.timestamp).toLocaleString())} · ${a.candidateCount} structures · ${escape(a.endpoint)}</small><div>${escape(a.modelId)} · ${escape(a.library)}</div><p class="hash">SHA-256 ${escape(a.artifactSha256)}</p><small>All source data and predictions are synthetic.</small></article>`).join(''):'<p class="muted">No saved runs yet.</p>'}
function setView(v){
  // Keep the former screening destination as an alias to its single Overview home.
  if(v==='screen')v='overview';
  view=v;document.body.dataset.workspace=v;
  $$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);if(b.dataset.view===v)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
  const names={overview:'Overview',library:'Results',statistics:'Statistics',shortlist:'Saved compounds',assistant:'AI assistant',method:'AI performance',audit:'History',assays:'Testing plan'};
  $('#crumb').textContent=names[v]||'Overview';
  $('.page-heading').hidden=v!=='overview';
  $('#workspaceHeading').hidden=!['library','shortlist','assistant'].includes(v);
  $('#workspaceTitle').textContent={library:'Explore your screening results',shortlist:'Your saved compounds',assistant:'Ask fairuz AI'}[v]||'';
  $('#workspaceDescription').textContent={library:'Compare ranked predictions and explore each compound in 3D.',shortlist:'Return to the candidates you saved in this browser.',assistant:'Understand this study through answers drawn from its existing evidence.'}[v]||'';
  $('#overview').hidden=!['overview','library','shortlist','assistant'].includes(v);
  $('#intro').hidden=v!=='overview';$('.stats').hidden=v!=='overview';$('.main-grid').hidden=v!=='overview';
  $('#summaryPanel').hidden=!['overview','library'].includes(v);
  $('.results-grid').hidden=!['library','shortlist','assistant'].includes(v);
  $('.candidates').hidden=!['library','shortlist'].includes(v);$('.agent').hidden=v!=='assistant';
  $('#assaySection').hidden=v!=='assays';$('#methodSection').hidden=v!=='method';$('#auditSection').hidden=v!=='audit';
  $('#statisticsSection').hidden=v!=='statistics';
  if(v==='statistics')showStatistics();else hideStatistics();
  page=1;render();
}
