$('#methodLink').onclick=()=>setView('method');$('#search').oninput=()=>{page=1;render()};$('#filter').onchange=()=>{page=1;render()};$('#prevPage').onclick=()=>{page--;render()};$('#nextPage').onclick=()=>{page++;render()};
$('#virus').onchange=()=>{const k=$('#virus').value;$('#selectedVirusName').textContent=study?.models[k]?.virus||{sars:'SARS-CoV-2',flu:'Influenza A',hcv:'Hepatitis C'}[k]||'Selected target';$('#unsupported').hidden=k!=='custom';$('#targetName').textContent=k==='custom'?'Unsupported target':study?.models[k].target||'Loading model metadata';$('#targetNote').textContent=k==='custom'?'No model exists — prediction is disabled':'Target-specific synthetic QSAR · not sequence inference';updateButtons()};
async function loadModel(key){if(modelCache[key])return modelCache[key];const res=await fetch(`models/${key}.json`);if(!res.ok)throw new Error(`Model download failed (${res.status}).`);const text=await res.text();const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text));const hash=Array.from(new Uint8Array(digest),x=>x.toString(16).padStart(2,'0')).join('');if(hash!==study.models[key].artifactSha256)throw new Error('Model artifact hash mismatch. Reload the study before screening.');const model=JSON.parse(text);modelCache[key]=model;return model}
async function runScreening({withSummary=true}={}){if(screenBusy||!study||$('#virus').value==='custom')return;screenBusy=true;updateButtons();$('#progress').hidden=false;$('#progress').textContent='Verifying the trained model artifact…';const key=$('#virus').value,library=$('#library').value;let succeeded=false,revealReady=false;try{const model=await loadModel(key);$('#progress').textContent='Evaluating 64 learned decision trees and matching training references…';await new Promise(r=>setTimeout(r,30));const candidates=library==='focused'?study.library.slice().sort((a,b)=>a.id.localeCompare(b.id)).slice(0,60):study.library;rows=rankCandidates(model,candidates,study.trainingReferences).map(c=>({...c,assayPlaceholder:makeAssayPlaceholder(c.id,key)}));succeeded=true;const meta=study.models[key];activeRun={id:`FZ-RUN-${Date.now().toString(36).toUpperCase()}`,timestamp:new Date().toISOString(),key,virus:meta.virus,target:meta.target,modelId:meta.id,artifactSha256:meta.artifactSha256,candidateCount:rows.length,endpoint:'Predicted synthetic pIC50; descending',library:library==='focused'?'Pilot: first 60 candidate IDs':'Full unseen candidate library',synthetic:true,model:meta,summary:null};audit.push({...activeRun,model:undefined,summary:undefined});audit=audit.slice(-100);persist();conversation=[];$('#messages').innerHTML='<div class="message assistant"><small>fairuz AI</small><p>Your results are ready. Ask me which compound ranks highest, how predictions work, or what the limitations mean. My answers come from this synthetic study’s evidence.</p></div>';$('#candidateStat').textContent=rows.length;$('#trainStat').textContent=meta.nTrain.toLocaleString();$('#rmseStat').textContent=numeric(meta.rmse,3);$('#search').value='';$('#filter').value='all';page=1;$('#runStrip').textContent=`${meta.virus} / ${meta.target} · ${activeRun.id} · ${rows.length} unseen structures · ${meta.id}`;$('#resultFacts').hidden=false;$('#resultFacts').innerHTML=`<span class="fact-chip"><small>TOP-RANKED COMPOUND</small><strong>${rows[0].id}</strong><span>Highest predicted activity in this run</span></span><span class="fact-chip"><small>PREDICTED ACTIVITY</small><strong>${numeric(rows[0].prediction,3)}</strong><span>Synthetic pIC50 · higher ranks first</span></span><span class="fact-chip"><small>MODEL UNCERTAINTY</small><strong>${numeric(rows[0].treeSd,3)}</strong><span>Tree SD · not a confidence interval</span></span><span class="fact-chip"><small>PREDICTION ERROR</small><strong>${numeric(meta.rmse,3)}</strong><span>Validation RMSE · artificial labels</span></span>`;$('#aiSummary').hidden=true;$('#aiSummary').textContent='';$('#summaryStatus').textContent='Your results are ready. Generate an AI summary to explore the study evidence and its sources.';$('#export').disabled=false;$('#exportCsv').disabled=false;render();plot();if(view==='screen')setView('overview');toast(`ML screening complete: ${rows.length} structures ranked.`);revealReady=true}catch(e){$('#loadError').hidden=false;$('#loadError').textContent=e.message;toast('Screening failed; no new results were created.')}finally{screenBusy=false;$('#progress').hidden=true;updateButtons()}if(revealReady){updateStatistics(activeRun,rows);screeningCompleted(activeRun,rows)}if(withSummary&&succeeded)await generateSummary()}
$('#screenForm').onsubmit=e=>{e.preventDefault();runScreening({withSummary:$('#autoSummary').checked})};
function toggleSave(id){saved.has(id)?saved.delete(id):saved.add(id);persist();render()}
document.addEventListener('click',e=>{const s=e.target.closest('[data-save]');if(s){toggleSave(s.dataset.save);return}const b=e.target.closest('[data-detail]');if(b)showDetail(b.dataset.detail)});
function showDetail(id){const c=rows.find(c=>c.id===id);if(!c||!activeRun)return;const names=['Molecular weight','LogP','Polar surface area (Å²)','H-bond donors','H-bond acceptors','Rotatable bonds','Fraction sp3','Aromatic rings'];$('#detailContent').innerHTML=`<div class="eyebrow">SYNTHETIC CANDIDATE · RANK ${c.rank} OF ${rows.length}</div><h2 style="font-size:27px;margin:10px 0">${c.id}</h2><p class="muted">${escape(activeRun.virus)} · ${escape(activeRun.target)} · no experimental evidence</p><code class="smiles">${escape(c.smiles)}</code><div class="detail-metrics"><div><strong>${numeric(c.prediction,3)}</strong><small>Predicted synthetic pIC50</small></div><div><strong>${nm(c.equivalentNm)}</strong><small>Equivalent synthetic IC50 · nM</small></div><div><strong>${numeric(c.treeSd,3)}</strong><small>Tree SD · uncalibrated</small></div></div><div class="inline-warning">Artificial endpoint only. This structure has not been shown to bind this target, inhibit a virus, or be safe. Rank is not clinical compatibility.</div><details class="learn-more advanced-structure"><summary>Molecular descriptors &amp; training references</summary><div class="detail-section"><h3>Molecular descriptors used by the model</h3><div class="mini-metrics">${names.map((n,i)=>`<span>${n}: <strong>${numeric(c.features[i],i===3||i===4||i===5||i===7?0:2)}</strong></span>`).join('')}</div></div><div class="detail-section"><h3>Nearest synthetic training references</h3><p>Morgan fingerprint similarity is structural context, not evidence of efficacy.</p>${c.neighbors.map(n=>`<div class="neighbor"><strong>${n.id}</strong> · Tanimoto ${numeric(n.similarity,3)} · synthetic training label ${numeric(n.labels[activeRun.key],3)} pIC50<code class="smiles">${escape(n.smiles)}</code></div>`).join('')}</div></details><div class="detail-section"><h3>Synthetic assay placeholders - NOT MEASURED</h3><p>Illustrative mean &plusmn; sample SD, 3 simulated values per endpoint. No experiment has been performed.</p><div class="mini-metrics"><span>IC50: <strong>${numeric(c.assayPlaceholder.ic50.mean,3)} &plusmn; ${numeric(c.assayPlaceholder.ic50.sd,3)} &micro;M</strong></span><span>EC50: <strong>${numeric(c.assayPlaceholder.ec50.mean,3)} &plusmn; ${numeric(c.assayPlaceholder.ec50.sd,3)} &micro;M</strong></span><span>CC50: <strong>${numeric(c.assayPlaceholder.cc50.mean,3)} &plusmn; ${numeric(c.assayPlaceholder.cc50.sd,3)} &micro;M</strong></span><span>SI (CC50/EC50): <strong>${numeric(c.assayPlaceholder.selectivityIndex,2)}</strong></span></div></div><div class="detail-section"><h3>Prediction provenance</h3><p>${escape(activeRun.modelId)} · 64 fitted trees · 1,680 synthetic fitting records</p><p class="hash">Artifact SHA-256 ${activeRun.artifactSha256}</p></div><div class="detail-actions"><button class="button primary" id="detailSave">${saved.has(c.id)?'Remove from saved':'Save compound'}</button><button class="button light" id="askDetail">Ask AI about this candidate</button></div>`;$('#detailSave').onclick=()=>{toggleSave(c.id);$('#detail').close();toast('Saved compounds updated')};$('#askDetail').onclick=()=>{$('#detail').close();setView('assistant');ask(`Explain the prediction and uncertainty for ${c.id}.`)};openCompoundViewer(c)}
$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail'))$('#detail').close()};
function aiStatus(t){$('#aiStatus').textContent=t;if(aiBusy&&aiTask==='summary')$('#summaryStatus').textContent=t}
function ensureWorker(){if(worker)return;worker=new Worker(new URL('./ai-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data:d})=>{if(d.type==='progress'){if(d.status==='progress')aiStatus(`Loading AI model: ${Math.round(d.progress||0)}% · ${d.file||'weights'} (~25 MB summary / ~70 MB Q&A first use)`);else if(d.status==='initiate')aiStatus('Downloading open-source evidence model. First use may take a moment.');return}if(d.type==='ready'){workerReady=true;$('#aiBadge').textContent='MODEL READY';return}if(d.type==='generating'){aiStatus('AI is selecting relevant study evidence...');return}if(['result','error','loaded'].includes(d.type)){const task=pending.get(d.id);if(!task)return;pending.delete(d.id);clearTimeout(task.timer);d.type==='error'?task.reject(new Error(d.error)):task.resolve(d)}};worker.onerror=e=>{for(const task of pending.values()){clearTimeout(task.timer);task.reject(new Error(e.message||'AI worker failed to load. Check internet access and retry.'))}pending.clear();worker?.terminate();worker=null;workerReady=false;$('#aiBadge').textContent='LOAD FAILED'}}
function invokeAI(payload){ensureWorker();const id=++requestId;return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{pending.delete(id);worker?.terminate();worker=null;workerReady=false;$('#aiBadge').textContent='TIMED OUT';reject(new Error('AI inference timed out. Try again on a desktop browser with more available memory.'))},300000);pending.set(id,{resolve,reject,timer});worker.postMessage({...payload,id})})}
function researchFacts(question=''){
 if(!activeRun)return [];
 const m=activeRun.model,matched=rows.filter(c=>question.toUpperCase().includes(c.id));
 const rankMatch=question.match(/rank(?:ed)?\s*(\d+)/i);if(rankMatch){const c=rows.find(c=>c.rank===Number(rankMatch[1]));if(c)matched.push(c)}
 const chosen=[...new Map([...rows.slice(0,3),...rows.slice(-1),...matched].map(c=>[c.id,c])).values()];
 const facts=chosen.map((c,i)=>({id:'C'+String(i+1).padStart(2,'0'),text:`${c.rank===1?'The first-ranked compound is':`The compound at rank ${c.rank} is`} ${c.id}, with predicted synthetic pIC50 of ${numeric(c.prediction,3)}, equivalent synthetic IC50 of ${nm(c.equivalentNm)} nM, and tree standard deviation of ${numeric(c.treeSd,3)}. Its maximum similarity to a synthetic training structure is ${numeric(c.similarity,3)}.`}));
 facts.push(
 ...chosen.map((c,i)=>({id:'P'+String(i+1).padStart(2,'0'),text:`The assay placeholders for ${c.id} are IC50 ${numeric(c.assayPlaceholder.ic50.mean,3)} micromolar, EC50 ${numeric(c.assayPlaceholder.ec50.mean,3)} micromolar and CC50 ${numeric(c.assayPlaceholder.cc50.mean,3)} micromolar. Placeholder selectivity index is ${numeric(c.assayPlaceholder.selectivityIndex,2)}, calculated as CC50 divided by EC50. These are fabricated display values, not measurements or model predictions. No experiment was performed.`})),
 {id:'S01',scope:true,text:'All structures and activity labels in this study are generated synthetic data. These are model predictions, not measured biological results. No real antiviral activity, treatment efficacy, safety or clinical compatibility can be inferred.'},
 {id:'S02',scope:true,text:'No patient records, clinical trials or laboratory assay results are included. This synthetic demonstration cannot nominate an effective treatment, determine a safe dose, or establish a cure.'},
 {id:'M01',text:`The selected synthetic context is ${activeRun.virus}, labelled ${activeRun.target}. The ranking model is a trained random forest with 64 decision trees and 264 molecular features. This is not a DeepPurpose checkpoint.`},
 {id:'M02',text:`The random forest learned from ${m.nTrain} synthetic fitting records. There are ${m.nValidation} separate synthetic validation structures and ${rows.length} unseen structures in this screening run. Fitting, validation and screening structures have distinct canonical identities.`},
 {id:'M03',text:`Validation root mean squared error (RMSE) is ${numeric(m.rmse,3)} synthetic pIC50 units; mean absolute error (MAE) is ${numeric(m.mae,3)} and R-squared is ${numeric(m.r2,3)}. These metrics measure recovery of artificial labels only. The mean-prediction baseline RMSE is ${numeric(m.baselineRmse,3)}.`},
 {id:'M04',text:'Compounds are ranked by predicted synthetic pIC50, from highest to lowest. Higher pIC50 mathematically means lower IC50. Equivalent synthetic IC50 in nM is 10 raised to (9 minus pIC50). Neither endpoint is an experimental measurement.'},
 {id:'U01',text:'Tree standard deviation reports uncalibrated disagreement among the 64 decision trees. It is not a confidence interval and is not a probability of efficacy.'},
 {id:'U02',text:'Training similarity is the maximum Morgan fingerprint Tanimoto similarity to any synthetic fitting structure. Similarity below 0.4 receives a heuristic low-similarity flag. That threshold has not been biologically validated.'},
 {id:'D01',text:'The dataset has 2400 RDKit-valid generated molecular structures. Inputs contain eight physicochemical descriptors plus 256 Morgan fingerprint bits with radius 2. Valid SMILES do not establish chemical availability or synthetic feasibility.'},
 {id:'D02',text:'Artificial descriptor-based response functions with added noise generate the synthetic activity labels. A molecule-disjoint random split uses fixed seeds. No scaffold, temporal, external, biological or clinical validation was performed.'},
 {id:'S03',scope:true,text:'No model supports an arbitrary new virus or protein sequence. Active learning would require new measured outcomes and model retraining; neither occurs during this screening demonstration.'},
 {id:'A01',text:'The AI summary is extractive: a neural sentence-embedding model selects relevant exact study statements. Questions use neural evidence retrieval and a DistilBERT extractive question-answering model. Answers are drawn from study records, not generated free-form. Source excerpts remain visible for verification.'}
 );return facts;
}
function addMessage(role,text){const d=document.createElement('div');d.className='message '+role;const s=document.createElement('small');s.textContent=role==='user'?'YOU':'fairuz AI · STUDY EVIDENCE';const p=document.createElement('p');p.textContent=text;d.append(s,p);$('#messages').append(d);$('#messages').scrollTop=$('#messages').scrollHeight;return d}
async function generateSummary(){if(!activeRun||aiBusy)return;aiTask='summary';aiBusy=true;updateButtons();const runId=activeRun.id;$('#summaryStatus').textContent='Loading the neural evidence-selection model...';$('#aiBadge').textContent=workerReady?'GENERATING':'LOADING MODEL';try{const result=await invokeAI({type:'summarise',facts:researchFacts()});if(activeRun?.id===runId){activeRun.summary={text:result.text,model:result.model,revision:result.revision,method:result.method,sources:result.items,generatedAt:new Date().toISOString()};$('#aiSummary').textContent=result.text;$('#aiSummary').hidden=false;$('#summaryStatus').textContent=`AI-selected evidence for ${runId}. Bracketed references identify exact study statements.`}}catch(e){if(activeRun?.id===runId){$('#summaryStatus').textContent='AI summary unavailable: '+e.message;$('#aiSummary').hidden=true}toast('AI did not return a summary. Retry when the model can load.')}finally{aiBusy=false;$('#aiBadge').textContent=workerReady?'MODEL READY':'MODEL NOT LOADED';aiStatus(workerReady?'On-device AI ready | answers include source evidence':'AI needs internet access to download its model');updateButtons()}}
async function ask(q){q=q.trim();if(!q||aiBusy)return;if(!activeRun){toast('Run screening before asking about results.');return}addMessage('user',q);const runId=activeRun.id;aiTask='chat';aiBusy=true;updateButtons();$('#chatInput').value='';$('#aiBadge').textContent=workerReady?'GENERATING':'LOADING MODEL';try{const result=await invokeAI({type:'answer',question:q,facts:researchFacts(q)});if(activeRun?.id!==runId){addMessage('assistant','The screening context changed while the answer was generating. Please ask again for the new run.');return}addMessage('assistant',result.text);conversation.push({role:'user',content:q},{role:'assistant',content:result.text})}catch(e){const d=addMessage('assistant','AI response unavailable: '+e.message);d.classList.add('section-error')}finally{aiBusy=false;$('#aiBadge').textContent=workerReady?'MODEL READY':'MODEL NOT LOADED';aiStatus(workerReady?'DistilBERT + MiniLM | on-device evidence extraction':'Model unavailable — retry to download');updateButtons()}}
$('#assaySearch').oninput=renderAssays;$('#assayExport').onclick=()=>{if(!activeRun)return;download(`fairouz-${activeRun.id}-ASSAY-PLACEHOLDERS.csv`,assayCsv(rows),'text/csv')};$('#summarise').onclick=generateSummary;$('#chatForm').onsubmit=e=>{e.preventDefault();ask($('#chatInput').value)};$$('[data-prompt]').forEach(b=>b.onclick=()=>ask(b.dataset.prompt));
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
$('#export').onclick=()=>{if(!activeRun)return;download(`fairouz-${activeRun.id}.json`,JSON.stringify({study:'FZ-SYN-2302',synthetic:true,disclaimer:'No biological or clinical validity. All activity labels are artificially generated.',exportedAt:new Date().toISOString(),run:activeRun,columns:{prediction:'Synthetic pIC50 (-log10 mol/L)',equivalentNm:'10^(9-prediction); not measured',treeSd:'Uncalibrated tree disagreement',similarity:'Maximum synthetic training Morgan fingerprint Tanimoto'},results:rows.map(c=>({...c,shortlisted:saved.has(c.id)})),shortlistedIds:[...saved]},null,2),'application/json');toast('Reproducible run report exported')};
$('#exportCsv').onclick=()=>{if(!activeRun)return;const quote=s=>'"'+String(s).replaceAll('"','""')+'"';const header=['run_id','model_id','synthetic','rank','compound_id','smiles','predicted_synthetic_pIC50','equivalent_synthetic_IC50_nM','uncalibrated_tree_SD','max_training_tanimoto','shortlisted'];const lines=[header.join(','),...rows.map(c=>[activeRun.id,activeRun.modelId,true,c.rank,c.id,c.smiles,c.prediction,c.equivalentNm,c.treeSd,c.similarity,saved.has(c.id)].map(quote).join(','))];download(`fairouz-${activeRun.id}.csv`,lines.join('\r\n'),'text/csv');toast('Ranked synthetic results exported')};$('#exportAudit').onclick=()=>download('fairouz-audit.json',JSON.stringify({synthetic:true,runs:audit},null,2),'application/json');
function modelCards(){$('#modelCards').innerHTML=Object.values(study.models).map(m=>`<article class="model-card"><h3>${escape(m.virus)}</h3><p>${escape(m.target)}</p><dl><dt>Fitting structures</dt><dd>${m.nTrain}</dd><dt>Validation structures</dt><dd>${m.nValidation}</dd><dt>Validation RMSE</dt><dd>${numeric(m.rmse,3)}</dd><dt>Mean-baseline RMSE</dt><dd>${numeric(m.baselineRmse,3)}</dd><dt>Validation MAE</dt><dd>${numeric(m.mae,3)}</dd><dt>Validation R²</dt><dd>${numeric(m.r2,3)}</dd><dt>Trees / seed</dt><dd>${m.trees} / ${m.seed}</dd></dl><p class="hash">${m.id}<br>SHA-256 ${m.artifactSha256}</p><small>Metrics apply only to generated labels.</small></article>`).join('')}
async function init(){try{const response=await fetch('research-data.json');if(!response.ok)throw new Error('Synthetic study data could not be loaded.');study=await response.json();if(!study.synthetic||study.schemaVersion!==2)throw new Error('Unexpected study format.');const validIds=new Set(study.library.map(c=>c.id));saved=new Set([...saved].filter(id=>validIds.has(id)));$('#navTotal').textContent=study.library.length;modelCards();updateButtons();await runScreening({withSummary:false})}catch(e){$('#loadError').hidden=false;$('#loadError').textContent=e.message+' Please reload the page.';$('#summaryStatus').textContent='Study loading failed. No model results are available.'}}
configureTopResults({onDetails:id=>{$('nav [data-view="library"]').click();$('.candidates').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});showDetail(id)},onExplore:()=>{$('nav [data-view="library"]').click();$('.candidates').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#search').focus({preventScroll:true})}});
configureStatistics({onDetails:showDetail,onOverview:()=>setView('overview'),onAssistant:()=>{setView('assistant');$('#chatInput').focus({preventScroll:true})}});
setView('overview');
init();
